def metric(data: pd.DataFrame) -> float:
    import numpy as np

    matches = []
    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        if a_wins > b_wins:
            tally_pred = 0
        elif b_wins > a_wins:
            tally_pred = 1
        else:
            continue

        matches.append(row['response'] == tally_pred)

    if not matches:
        return 0.5
    return float(np.mean(matches))

